"""Word-count utilities for the wordstats mock project."""


def count_words(text):
    """Return a mapping of lowercased words to occurrence counts.

    Punctuation is stripped from token edges; tokens that are only
    punctuation are ignored.
    """
    counts = {}
    for raw in text.lower().split():
        word = raw.strip(".,;:!?-\"'()")
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts

"""Rare-word filtering for wordstats."""


def filter_rare_words(counts, n):
    """Return a new mapping containing only words with count <= n.

    The input mapping is not modified.
    """
    return {word: count for word, count in counts.items() if count <= n}

"""Rare-word selection for the wordstats mock project."""


def select_rare(counts, n):
    """Return a new mapping keeping only words whose count is <= n.

    The input mapping is not modified. Raises ValueError when n is
    not a positive integer.
    """
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("N must be a positive integer")
    return {word: count for word, count in counts.items() if count <= n}

"""Top-N filtering for word counts (pure logic, no I/O)."""


def filter_top_words(counts, n):
    """Return a NEW mapping containing only the n most frequent words.

    Ties are broken alphabetically: when words tie at the cutoff, the
    word earlier in alphabetical order wins. ``counts`` is not modified.
    """
    if n <= 0:
        return {}
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return dict(ranked[:n])

"""Top-word selection for the wordstats mock project."""


def select_top(counts, n):
    """Return a new mapping keeping only the n most frequent words.

    Words are ordered by descending count, then ascending word, and the
    first n are kept. The input mapping is not modified.
    """
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("N must be a positive integer")
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return dict(ordered[:n])

"""Unit tests for wordstats.rarewords.filter_rare_words."""

import unittest

from wordstats.rarewords import filter_rare_words


class TestFilterRareWords(unittest.TestCase):
    def test_inclusive_boundary_keeps_count_equal_to_n(self):
        counts = {"a": 2, "b": 3}
        result = filter_rare_words(counts, 3)
        self.assertEqual(result, {"a": 2, "b": 3})

    def test_excludes_counts_greater_than_n(self):
        counts = {"a": 1, "b": 5}
        result = filter_rare_words(counts, 2)
        self.assertEqual(result, {"a": 1})
        self.assertNotIn("b", result)

    def test_empty_result_when_no_word_qualifies(self):
        counts = {"a": 7, "b": 9}
        result = filter_rare_words(counts, 2)
        self.assertEqual(result, {})

    def test_empty_counts_input(self):
        result = filter_rare_words({}, 3)
        self.assertEqual(result, {})

    def test_input_mapping_is_not_modified(self):
        counts = {"a": 1, "b": 5}
        filter_rare_words(counts, 2)
        self.assertEqual(counts, {"a": 1, "b": 5})


if __name__ == "__main__":
    unittest.main()

